assert len(sources) == 13
assert {a['number'] for a in sources} == set(explanations)
answers = []
for source in sources:
    number = source['number']
    stem = number.replace(' ', '_')
    if number == '125-0 A':
        files = [BASE / 'drafts' / f'{stem}_{i:02}.xml' for i in range(1, 5)]
    else:
        files = [BASE / 'drafts' / f'{stem}.xml']
    proposal = '\n'.join(p.read_text().strip() for p in files)
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(proposed_xml=proposal, **explanations[number], status='rewrite_draft')
    answers.append(item)

(BASE / 'answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answers)} articles, {sum(len(a["proposed_xml"]) for a in answers)} caractères de texte proposé')
